document.addEventListener('DOMContentLoaded', function () {

    const API_URL = (window.APP_BASE_URL||window.location.origin||"").replace(/\/$/,"") + '/profileedit.php';
    const IS_GUEST = !!window.IS_GUEST;
    const notifyGuest = (msg) => {
        try {
            if (typeof notifyGuestRestriction === 'function') {
                notifyGuestRestriction(msg);
                return;
            }
        } catch (_) { }
        alert(msg || 'Login required');
    };

    // --- Elements ---
    const sidebarUserInfo = document.getElementById('sidebarUserInfo');
    const preferenceboxOverlay = document.getElementById('preferenceboxOverlay');
    const preferenceboxCloseBtn = document.getElementById('preferenceboxCloseBtn');
    const tabLinks = document.querySelectorAll('.preferencebox-tab-link');
    const tabContents = document.querySelectorAll('.preferencebox-tab-content');
    const sidebarUserMenu = document.getElementById('sidebarUserMenu');

    const changePhotoBtn = document.getElementById('changePhotoBtn');
    const profilePhotoInput = document.getElementById('profilePhotoInput');
    const saveGeneralBtn = document.getElementById('saveGeneralBtn');
    const savePreferenceBtn = document.getElementById('savePreferenceBtn');
    const saveStudentVerificationBtn = document.getElementById('saveStudentVerificationBtn');
    const clearMemoryBtn = document.getElementById('clearMemoryBtn');
    const currentMemoryBox = document.getElementById('currentMemoryBox');
    const generalAlertBox = document.getElementById('generalAlertBox');
    const preferenceAlertBox = document.getElementById('preferenceAlertBox');
    const studentVerificationAlertBox = document.getElementById('studentVerificationAlertBox');
    const billingHistoryBody = document.getElementById('billingHistoryBody');
    const changePasswordBtn = document.getElementById('changePasswordBtn');
    const passwordAlertBox = document.getElementById('passwordAlertBox');
    const connectGoogleBtn = document.getElementById('connectGoogleBtn');
    const googleConnectedBadge = document.getElementById('googleConnectedBadge');
    const deleteAccountBtn = document.getElementById('deleteAccountBtn');
    const deleteAccountModal = document.getElementById('deleteAccountModal');
    const cancelDeleteAccountBtn = document.getElementById('cancelDeleteAccountBtn');
    const confirmDeleteAccountBtn = document.getElementById('confirmDeleteAccountBtn');

    const publicProfileUrlInput = document.getElementById('publicProfileUrl');
    const seePublicProfileBtn = document.getElementById('seePublicProfileBtn');
    const copyPublicProfileLinkBtn = document.getElementById('copyPublicProfileLinkBtn');
    const publicProfileUsernameInput = document.getElementById('publicProfileUsername');
    const closePublicProfileInput = document.getElementById('closePublicProfile');
    const savePublicProfileBtn = document.getElementById('savePublicProfileBtn');
    const publicProfileAlertBox = document.getElementById('publicProfileAlertBox');
    const startLearningStreakBtn = document.getElementById('startLearningStreakBtn');
    const learningStreakStatus = document.getElementById('learningStreakStatus');
    const learningStreakNameInput = document.getElementById('learningStreakName');
    const endLearningStreakBtn = document.getElementById('endLearningStreakBtn');
    const learningStreakActive = document.getElementById('learningStreakActive');
    const learningStreakHistory = document.getElementById('learningStreakHistory');
    const learningStreakHistoryList = document.getElementById('learningStreakHistoryList');
    const learningStreakBadges = document.getElementById('learningStreakBadges');

    const schoolInput = document.getElementById('schoolInput');
    const notStudentInput = document.getElementById('notStudentInput');
    const subjectInput = document.getElementById('subjectInput');
    const schoolList = document.getElementById('school-list');
    const appBaseUrl = (window.APP_BASE_URL||window.location.origin||"").replace(/\/$/,"");

    const normalizeSchoolName = (value) => value.trim().toLowerCase();
    const setSchoolList = (names) => {
        const uniqueNames = Array.from(new Set(names.filter(Boolean)));
        const notListedOption = 'MY SCHOOL IS NOT LISTED';
        if (!uniqueNames.includes(notListedOption)) {
            uniqueNames.push(notListedOption);
        }
        window.SCHOOL_LIST = uniqueNames;
        window.SCHOOL_SET = new Set(uniqueNames.map(normalizeSchoolName));
        if (schoolList) {
            schoolList.innerHTML = '';
            uniqueNames.forEach((name) => {
                const option = document.createElement('option');
                option.value = name;
                schoolList.appendChild(option);
            });
        }
    };

    const loadSchoolList = async () => {
        if (window.SCHOOL_LIST && Array.isArray(window.SCHOOL_LIST) && window.SCHOOL_LIST.length > 0) {
            if (schoolList && schoolList.options.length === 0) {
                setSchoolList(window.SCHOOL_LIST);
            }
            return;
        }
        try {
            const res = await fetch(`${appBaseUrl}/allschools.json`, { cache: 'force-cache' });
            const data = await res.json();
            if (!Array.isArray(data)) return;
            const names = data.map((entry) => {
                if (typeof entry === 'string') return entry.trim();
                if (!entry || typeof entry !== 'object') return '';
                return (entry.name || entry.school || entry['School Name'] || '').toString().trim();
            }).filter(Boolean);
            if (names.length) {
                setSchoolList(names);
            }
        } catch (err) {
            console.error('Failed to load school list:', err);
        }
    };

    loadSchoolList();

    const profileLoader = document.getElementById('profileLoader'); // Loader element

    const baseUrl = (window.APP_BASE_URL||window.location.origin||"").replace(/\/$/,"");
    const profilePhotoEl = document.getElementById('profilePhoto');
    const sidebarAvatarEl = document.querySelector('.sidebar-footer-userinfo .user-avatar img');
    let profileImageBustToken = null;

    const withCacheBust = (value) => {
        const src = String(value || '').trim();
        if (!src) return src;
        if (src.startsWith('data:') || src.startsWith('blob:')) return src;
        if (!profileImageBustToken) return src;
        const join = src.includes('?') ? '&' : '?';
        return `${src}${join}v=${profileImageBustToken}`;
    };

    const applyProfileImage = (url) => {
        const src = withCacheBust(url);
        if (!src) return;
        if (profilePhotoEl) {
            profilePhotoEl.src = src;
            profilePhotoEl.loading = 'lazy';
            profilePhotoEl.decoding = 'async';
        }
        if (sidebarAvatarEl) {
            sidebarAvatarEl.src = src;
            sidebarAvatarEl.decoding = 'async';
        }
    };

    const cachedProfileImage = (typeof getProfileImageCache === 'function') ? getProfileImageCache() : '';
    if (cachedProfileImage) {
        applyProfileImage(cachedProfileImage);
    }

    const setPublicProfileAlert = (message, color) => {
        if (!publicProfileAlertBox) return;
        publicProfileAlertBox.style.display = 'block';
        publicProfileAlertBox.style.color = color || 'red';
        publicProfileAlertBox.textContent = message;
    };

    const formatDate = (value) => {
        if (!value) return '';
        const parsed = new Date(value);
        if (!isNaN(parsed.getTime())) {
            return parsed.toLocaleDateString();
        }
        return value;
    };

    const clearNode = (node) => {
        if (!node) return;
        while (node.firstChild) node.removeChild(node.firstChild);
    };

    const renderStreakBadges = (streakData) => {
        if (!learningStreakBadges) return;
        clearNode(learningStreakBadges);

        const progress = streakData && streakData.progress ? streakData.progress : {};
        const badgeList = [
            {
                key: 'silver',
                title: 'Silver Streak',
                target: 7,
                picture: '<picture><source srcset=\"https://fonts.gstatic.com/s/e/notoemoji/latest/1f948/512.webp\" type=\"image/webp\"><img src=\"https://fonts.gstatic.com/s/e/notoemoji/latest/1f948/512.gif\" alt=\"🥈\" width=\"32\" height=\"32\" loading=\"lazy\" decoding=\"async\"></picture>'
            },
            {
                key: 'gold',
                title: 'Gold Streak',
                target: 30,
                picture: '<picture><source srcset=\"https://fonts.gstatic.com/s/e/notoemoji/latest/1f947/512.webp\" type=\"image/webp\"><img src=\"https://fonts.gstatic.com/s/e/notoemoji/latest/1f947/512.gif\" alt=\"🥇\" width=\"32\" height=\"32\" loading=\"lazy\" decoding=\"async\"></picture>'
            },
            {
                key: 'diamond',
                title: 'Diamond Streak',
                target: 100,
                picture: '<picture><source srcset=\"https://fonts.gstatic.com/s/e/notoemoji/latest/1f48e/512.webp\" type=\"image/webp\"><img src=\"https://fonts.gstatic.com/s/e/notoemoji/latest/1f48e/512.gif\" alt=\"💎\" width=\"32\" height=\"32\" loading=\"lazy\" decoding=\"async\"></picture>'
            }
        ];

        badgeList.forEach((badge) => {
            const data = progress[badge.key] || {};
            const earned = data.earned || false;
            const percent = typeof data.percent === 'number' ? data.percent : 0;
            const remaining = typeof data.remaining === 'number' ? data.remaining : badge.target;

            const badgeEl = document.createElement('div');
            badgeEl.className = 'streak-badge';

            const icon = document.createElement('span');
            icon.className = 'streak-badge-emoji';
            icon.innerHTML = badge.picture;

            const content = document.createElement('div');
            const title = document.createElement('div');
            title.className = 'streak-badge-title';
            title.textContent = `${badge.title} (${badge.target} days)`;

            const meta = document.createElement('div');
            meta.className = 'streak-badge-meta';
            meta.textContent = earned ? 'Earned' : `${remaining} days left to earn`;

            const progressWrap = document.createElement('div');
            progressWrap.className = 'streak-progress';
            const bar = document.createElement('div');
            bar.className = 'streak-progress-bar';
            bar.style.width = `${Math.min(100, Math.max(0, percent))}%`;
            progressWrap.appendChild(bar);

            content.appendChild(title);
            content.appendChild(meta);
            content.appendChild(progressWrap);

            badgeEl.appendChild(icon);
            badgeEl.appendChild(content);

            learningStreakBadges.appendChild(badgeEl);
        });
    };

    const renderStreakHistory = (streakData) => {
        if (!learningStreakHistory || !learningStreakHistoryList) return;
        clearNode(learningStreakHistoryList);
        const history = streakData && Array.isArray(streakData.history) ? streakData.history : [];
        if (history.length === 0) {
            learningStreakHistory.style.display = 'none';
            return;
        }
        learningStreakHistory.style.display = 'block';
        let rendered = 0;
        history.forEach((item) => {
            if (item.status === 'active') return;
            const name = item.name || 'Learning Streak';
            const dayCount = Number(item.day_count) || 0;
            const start = formatDate(item.started_at);
            const end = item.ended_at ? formatDate(item.ended_at) : 'Ongoing';
            const li = document.createElement('li');
            li.textContent = `${name} • ${dayCount} day${dayCount === 1 ? '' : 's'} • ${start} → ${end}`;
            learningStreakHistoryList.appendChild(li);
            rendered += 1;
        });
        if (rendered === 0) {
            learningStreakHistory.style.display = 'none';
        }
    };

    const renderActiveStreak = (streakData) => {
        if (!learningStreakActive) return;
        if (!streakData || !streakData.active || !streakData.active_streak) {
            learningStreakActive.style.display = 'none';
            learningStreakActive.textContent = '';
            return;
        }
        const active = streakData.active_streak;
        const dayCount = Number(active.day_count) || 0;
        const lastEntry = active.last_entry_date ? `Last check-in ${formatDate(active.last_entry_date)}` : 'No check-in yet';
        learningStreakActive.textContent = `${active.name || 'Learning Streak'} • Day ${dayCount} • ${lastEntry}`;
        learningStreakActive.style.display = 'block';
    };

    const updatePublicProfileUI = (data) => {
        const token = data.public_profile_token || (data.user ? data.user.public_profile_token : '');
        const username = data.public_profile_username || (data.user ? data.user.public_profile_username : '');
        const enabled = (typeof data.public_profile_enabled !== 'undefined')
            ? Number(data.public_profile_enabled) === 1
            : (data.user ? Number(data.user.public_profile_enabled) === 1 : true);

        const slug = (username && username.trim() !== '') ? username.trim() : (token || '');
        const url = slug ? `${baseUrl}/${slug}` : '';

        if (publicProfileUrlInput) publicProfileUrlInput.value = url;
        if (publicProfileUsernameInput) publicProfileUsernameInput.value = username || '';
        if (closePublicProfileInput) closePublicProfileInput.checked = !enabled;

        if (seePublicProfileBtn) {
            seePublicProfileBtn.href = url || '#';
            seePublicProfileBtn.textContent = enabled ? 'See Public Profile' : 'Public Profile Closed';
            seePublicProfileBtn.style.pointerEvents = enabled && url ? 'auto' : 'none';
            seePublicProfileBtn.style.opacity = enabled && url ? '1' : '0.6';
        }

        if (copyPublicProfileLinkBtn) {
            copyPublicProfileLinkBtn.disabled = !(enabled && url);
        }

        const streakData = data.learning_streak || (data.user ? data.user.learning_streak : null);
        const activeStreak = streakData && streakData.active && streakData.active_streak ? streakData.active_streak : null;
        const dayCount = activeStreak ? Number(activeStreak.day_count) || 0 : 0;

        if (learningStreakStatus) {
            if (activeStreak) {
                learningStreakStatus.textContent = `${activeStreak.name || 'Learning Streak'} • Day ${dayCount}`;
            } else {
                learningStreakStatus.textContent = 'Not started';
            }
        }

        if (startLearningStreakBtn) {
            startLearningStreakBtn.disabled = !!activeStreak;
            startLearningStreakBtn.textContent = activeStreak ? 'Learning Streak Started' : 'Start Learning Streak';
        }

        if (endLearningStreakBtn) {
            endLearningStreakBtn.style.display = activeStreak ? 'inline-flex' : 'none';
        }

        if (learningStreakNameInput) {
            learningStreakNameInput.disabled = !!activeStreak;
            if (activeStreak && activeStreak.name) {
                learningStreakNameInput.value = activeStreak.name;
            } else if (!activeStreak) {
                learningStreakNameInput.value = '';
            }
        }

        renderActiveStreak(streakData);
        renderStreakHistory(streakData);
        renderStreakBadges(streakData || {});
    };

    const activatePreferenceTab = (tabId) => {
        if (!tabId) return;
        tabLinks.forEach(l => l.classList.toggle('active', l.getAttribute('data-tab') === tabId));
        tabContents.forEach(content => {
            if (content.id === tabId) content.classList.add('active');
            else content.classList.remove('active');
        });
    };

    const openPreferenceBox = (tabId) => {
        if (IS_GUEST) {
            notifyGuest('Log in to access preferences and memory.');
            return;
        }
        if (!preferenceboxOverlay) return;
        preferenceboxOverlay.style.display = 'flex';
        preferenceboxOverlay.classList.add('active');
        if (tabId) activatePreferenceTab(tabId);
    };
    const closePreferenceBox = () => {
        if (!preferenceboxOverlay) return;
        preferenceboxOverlay.style.display = 'none';
        preferenceboxOverlay.classList.remove('active');
    };
    window.openPreferenceBox = openPreferenceBox;

    const setUserMenuOpen = (open) => {
        if (!sidebarUserMenu || !sidebarUserInfo) return;
        sidebarUserMenu.classList.toggle('is-visible', !!open);
        sidebarUserMenu.setAttribute('aria-hidden', open ? 'false' : 'true');
        sidebarUserInfo.setAttribute('aria-expanded', open ? 'true' : 'false');
    };

    const toggleUserMenu = () => {
        if (!sidebarUserMenu || !sidebarUserInfo) return;
        const isOpen = sidebarUserMenu.classList.contains('is-visible');
        setUserMenuOpen(!isOpen);
    };

    const handleUserMenuAction = (action) => {
        if (!action) return;
        if (action === 'logout') {
            window.location.href = `${appBaseUrl}/auth/signout`;
            return;
        }
        if (IS_GUEST) {
            notifyGuest('Log in to continue.');
            return;
        }
        if (action === 'upgrade') {
            if (typeof openPreferenceBoxWithBillingTab === 'function') {
                openPreferenceBoxWithBillingTab();
            } else {
                openPreferenceBox('billing');
            }
            return;
        }
        if (action === 'settings') {
            openPreferenceBox('general');
            return;
        }
        if (action === 'help') {
            openPreferenceBox('app');
        }
    };

    // --- Open/Close Lightbox ---
    sidebarUserInfo.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        if (!sidebarUserMenu) {
            openPreferenceBox('general');
            return;
        }
        toggleUserMenu();
    });

    if (sidebarUserMenu) {
        sidebarUserMenu.addEventListener('click', (event) => {
            const btn = event.target.closest('[data-action]');
            if (!btn) return;
            event.preventDefault();
            const action = btn.dataset.action;
            setUserMenuOpen(false);
            handleUserMenuAction(action);
        });
    }

    preferenceboxCloseBtn.addEventListener('click', () => {
        closePreferenceBox();
    });

    preferenceboxOverlay.addEventListener('click', (event) => {
        if (event.target === preferenceboxOverlay) {
            closePreferenceBox();
        }
    });

    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') {
            if (preferenceboxOverlay && preferenceboxOverlay.style.display === 'flex') {
                closePreferenceBox();
            }
            setUserMenuOpen(false);
        }
    });

    document.addEventListener('click', (event) => {
        if (!sidebarUserMenu || !sidebarUserInfo) return;
        if (!sidebarUserMenu.classList.contains('is-visible')) return;
        if (sidebarUserMenu.contains(event.target) || sidebarUserInfo.contains(event.target)) return;
        setUserMenuOpen(false);
    });

    // --- Tab Switching Logic ---
    tabLinks.forEach(link => {
        link.addEventListener('click', (event) => {
            event.preventDefault();
            const tabId = link.getAttribute('data-tab');

            tabLinks.forEach(l => l.classList.remove('active'));
            link.classList.add('active');

            tabContents.forEach(content => {
                if (content.id === tabId) content.classList.add('active');
                else content.classList.remove('active');
            });
        });
    });

    // --- Profile Photo Upload Trigger ---
    if (changePhotoBtn && profilePhotoInput) {
        changePhotoBtn.addEventListener('click', () => {
            profilePhotoInput.click();
        });
    }
    // --- Loader when uploading profile photo ---
    if (profilePhotoInput) {
        profilePhotoInput.addEventListener('change', () => {
            // If a file is selected, show loader
            if (profilePhotoInput.files && profilePhotoInput.files.length > 0) {
                if (profileLoader) {
                    profileLoader.style.display = 'inline-block';
                    profileLoader.style.color = 'var(--text-secondary)';
                    profileLoader.textContent = 'Ready to upload';
                }
                const file = profilePhotoInput.files[0];
                if (file) {
                    const previewUrl = URL.createObjectURL(file);
                    applyProfileImage(previewUrl);
                    setTimeout(() => {
                        try { URL.revokeObjectURL(previewUrl); } catch (_) { }
                    }, 12000);
                }
            }
        });
    }

    // --- Load all saved data ---
    async function loadProfileData() {
        try {
            if (IS_GUEST) {
                if (currentMemoryBox) currentMemoryBox.textContent = 'Log in to use memory.';
                return;
            }
            const res = await fetch(`${API_URL}?action=load`);
            const data = await res.json();
            if (!data.success) return;

            // --- Load General Info ---
            if (data.user) {
                if (document.getElementById('firstName')) document.getElementById('firstName').value = data.user.first_name || '';
                if (document.getElementById('lastName')) document.getElementById('lastName').value = data.user.last_name || '';
                if (document.getElementById('email')) document.getElementById('email').value = data.user.email || '';
                if (document.getElementById('phone')) document.getElementById('phone').value = data.user.phone || '';
                const rawImage = data.user.image || data.user.profile_image || data.user.avatar || '';
                if (rawImage) {
                    const imgUrl = (typeof toFullImageUrl === 'function') ? toFullImageUrl(rawImage) : rawImage;
                    const finalUrl = withCacheBust(imgUrl);
                    applyProfileImage(finalUrl);
                    if (typeof setProfileImageCache === 'function') {
                        setProfileImageCache(finalUrl);
                    }
                }
            }

            // --- Load Preferences ---
            if (schoolInput) schoolInput.value = data.school || '';
            if (notStudentInput) notStudentInput.checked = data.not_student == 1;

            if (subjectInput && data.interests && Array.isArray(data.interests)) {
                subjectInput.value = data.interests.join(', ');
            }

            if (data.preference) {
                const toneRadio = document.querySelector(`input[name="aiTone"][value="${data.preference}"]`);
                if (toneRadio) toneRadio.checked = true;
            }

            // --- Load Memory ---
            if (currentMemoryBox) {
                currentMemoryBox.textContent = data.user.memory || 'No memory stored.';
            }

  // --- Load Billing History ---
if (billingHistoryBody && Array.isArray(data.billing)) {
    billingHistoryBody.innerHTML = '';

    data.billing.forEach(tx => {
        const statusValue = (tx.status_indicator || '').trim();
        if (!statusValue) return;

        const tr = document.createElement('tr');
        const receiptUrl = ((window.APP_BASE_URL||window.location.origin||"").replace(/\/$/,"")) + `/receipt/${encodeURIComponent(tx.invoice_id)}`;
        tr.innerHTML = `
            <td>${tx.invoice_id}</td>
            <td>Rs. ${tx.amount}</td>
            <td>${tx.created_at}</td>
            <td>PAID</td>
            <td><a class="btn btn-secondary btn-sm" href="${receiptUrl}" target="_blank" rel="noopener">View receipt</a></td>
        `;
        billingHistoryBody.appendChild(tr);
    });
}

            // --- Connected Profiles ---
            if (connectGoogleBtn) {
                const baseUrl = (window.APP_BASE_URL||window.location.origin||"").replace(/\/$/,"");
                if (data.has_google_auth) {
                    connectGoogleBtn.innerHTML = '<i class="fab fa-google" style="color:#DB4437;"></i> Google Connected';
                    connectGoogleBtn.href = '#';
                    connectGoogleBtn.style.pointerEvents = 'none';
                    connectGoogleBtn.style.opacity = '0.6';
                    if (googleConnectedBadge) {
                        googleConnectedBadge.textContent = data.google_email ? `Connected: ${data.google_email}` : 'Connected';
                        googleConnectedBadge.style.display = 'inline-block';
                    }
                } else {
                    connectGoogleBtn.innerHTML = '<i class="fab fa-google" style="color:#DB4437;"></i> Connect with Google';
                    connectGoogleBtn.href = `${baseUrl}/auth/google?link=1`;
                    connectGoogleBtn.style.pointerEvents = 'auto';
                    connectGoogleBtn.style.opacity = '1';
                    if (googleConnectedBadge) googleConnectedBadge.style.display = 'none';
                }
            }

            // --- Load Public Profile ---
            updatePublicProfileUI(data);

        } catch (err) {
            console.error('Error loading profile data', err);
        }
    }

    loadProfileData();

    // --- Public Profile Actions ---
    if (copyPublicProfileLinkBtn) {
        copyPublicProfileLinkBtn.addEventListener('click', async () => {
            if (!publicProfileUrlInput || !publicProfileUrlInput.value) return;
            const text = publicProfileUrlInput.value;
            try {
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    await navigator.clipboard.writeText(text);
                    setPublicProfileAlert('Link copied to clipboard.', 'green');
                } else {
                    publicProfileUrlInput.select();
                    document.execCommand('copy');
                    setPublicProfileAlert('Link copied to clipboard.', 'green');
                }
            } catch (err) {
                setPublicProfileAlert('Failed to copy link.', 'red');
            }
        });
    }

    if (savePublicProfileBtn) {
        savePublicProfileBtn.addEventListener('click', async () => {
            const usernameRaw = publicProfileUsernameInput ? publicProfileUsernameInput.value.trim() : '';
            const closeProfile = closePublicProfileInput ? closePublicProfileInput.checked : false;

            if (usernameRaw !== '') {
                if (/\s/.test(usernameRaw)) {
                    setPublicProfileAlert('Username cannot contain spaces.', 'red');
                    return;
                }
                if (!/^[A-Za-z0-9_-]{3,30}$/.test(usernameRaw)) {
                    setPublicProfileAlert('Use 3-30 characters: letters, numbers, underscores, or dashes.', 'red');
                    return;
                }
            }

            const formData = new FormData();
            formData.append('action', 'public_profile');
            formData.append('username', usernameRaw);
            formData.append('close_public_profile', closeProfile ? '1' : '0');

            try {
                const res = await fetch(API_URL, { method: 'POST', body: formData });
                const result = await res.json();
                if (result.success) {
                    setPublicProfileAlert('Public profile updated.', 'green');
                    updatePublicProfileUI(result);
                } else {
                    setPublicProfileAlert(result.message || 'Failed to update public profile.', 'red');
                }
            } catch (err) {
                setPublicProfileAlert('Failed to update public profile.', 'red');
            }
        });
    }

    if (startLearningStreakBtn) {
        startLearningStreakBtn.addEventListener('click', async () => {
            const streakName = learningStreakNameInput ? learningStreakNameInput.value.trim() : '';
            if (!streakName) {
                setPublicProfileAlert('Please enter a streak name.', 'red');
                return;
            }
            if (streakName.length > 80) {
                setPublicProfileAlert('Streak name must be 80 characters or less.', 'red');
                return;
            }
            const formData = new FormData();
            formData.append('action', 'start_streak');
            formData.append('streak_name', streakName);

            try {
                const res = await fetch(API_URL, { method: 'POST', body: formData });
                const result = await res.json();
                if (result.success) {
                    loadProfileData();
                    setPublicProfileAlert('Learning streak started.', 'green');
                    if (typeof window.refreshStreakStatus === 'function') {
                        window.refreshStreakStatus();
                    }
                } else {
                    setPublicProfileAlert(result.message || 'Failed to start learning streak.', 'red');
                }
            } catch (err) {
                setPublicProfileAlert('Failed to start learning streak.', 'red');
            }
        });
    }

    if (endLearningStreakBtn) {
        endLearningStreakBtn.addEventListener('click', async () => {
            const formData = new FormData();
            formData.append('action', 'end_streak');

            try {
                const res = await fetch(API_URL, { method: 'POST', body: formData });
                const result = await res.json();
                if (result.success) {
                    loadProfileData();
                    setPublicProfileAlert('Learning streak ended.', 'green');
                    if (typeof window.refreshStreakStatus === 'function') {
                        window.refreshStreakStatus();
                    }
                } else {
                    setPublicProfileAlert(result.message || 'Failed to end learning streak.', 'red');
                }
            } catch (err) {
                setPublicProfileAlert('Failed to end learning streak.', 'red');
            }
        });
    }

    // --- Save General Settings ---
    if (saveGeneralBtn) {
        saveGeneralBtn.addEventListener('click', async () => {
            const firstName = document.getElementById('firstName').value.trim();
            const lastName = document.getElementById('lastName').value.trim();
            const email = document.getElementById('email').value.trim();
            const phone = document.getElementById('phone').value.trim();
            const photoFile = profilePhotoInput ? profilePhotoInput.files[0] : null;

            const formData = new FormData();
            formData.append('action', 'general');
            formData.append('firstName', firstName);
            formData.append('lastName', lastName);
            formData.append('email', email);
            formData.append('phone', phone);
            if (photoFile) formData.append('profilePhoto', photoFile);

            try {
                if (profileLoader && photoFile) {
                    profileLoader.style.display = 'inline-block';
                    profileLoader.style.color = 'var(--text-secondary)';
                    profileLoader.textContent = 'Uploading...';
                }
                const res = await fetch(API_URL, { method: 'POST', body: formData });
                const result = await res.json();
                if (profileLoader) {
                    if (photoFile) {
                        profileLoader.style.display = 'inline-block';
                        profileLoader.style.color = '#28a745';
                        profileLoader.textContent = 'Done';
                        setTimeout(() => {
                            profileLoader.style.display = 'none';
                        }, 1500);
                    } else {
                        profileLoader.style.display = 'none';
                    }
                }

                if (result.success) {
                    if (photoFile) {
                        profileImageBustToken = Date.now().toString();
                    }
                    generalAlertBox.style.display = 'block';
                    generalAlertBox.style.color = 'green';
                    generalAlertBox.textContent = 'Profile updated successfully!';
                    loadProfileData();
                } else {
                    generalAlertBox.style.display = 'block';
                    generalAlertBox.style.color = 'red';
                    generalAlertBox.textContent = 'Failed: ' + result.message;
                }
            } catch (err) {
                if (profileLoader) profileLoader.style.display = 'none';
                generalAlertBox.style.display = 'block';
                generalAlertBox.style.color = 'red';
                generalAlertBox.textContent = 'Failed to update profile.';
                console.error(err);
            }
        });
    }

    // --- Change Password (send reset link) ---
    if (changePasswordBtn) {
        changePasswordBtn.addEventListener('click', async () => {
            const emailField = document.getElementById('email');
            const email = emailField ? emailField.value.trim() : '';
            if (!email) {
                if (passwordAlertBox) {
                    passwordAlertBox.style.display = 'block';
                    passwordAlertBox.style.color = 'red';
                    passwordAlertBox.textContent = 'Email is required.';
                }
                return;
            }
            changePasswordBtn.disabled = true;
            try {
                const formData = new FormData();
                formData.append('action', 'request_password_reset');
                formData.append('email', email);
                const res = await fetch(API_URL, { method: 'POST', body: formData });
                const result = await res.json();
                const success = (result.success === true || result.success === 'true' || result.success === 1 || result.success === '1')
                    ? true
                    : (typeof result.success === 'boolean'
                        ? result.success
                        : (typeof result.e === 'boolean' ? !result.e : false));
                const message = result.message || result.m || (success ? 'Reset link sent.' : 'Failed to send reset link.');
                if (passwordAlertBox) {
                    passwordAlertBox.style.display = 'block';
                    passwordAlertBox.style.color = success ? 'green' : 'red';
                    passwordAlertBox.textContent = message;
                }
            } catch (err) {
                if (passwordAlertBox) {
                    passwordAlertBox.style.display = 'block';
                    passwordAlertBox.style.color = 'red';
                    passwordAlertBox.textContent = 'Failed to send reset link.';
                }
            } finally {
                changePasswordBtn.disabled = false;
            }
        });
    }

    // --- Save Preferences ---
    const showPreferenceAlert = (alertBox, message, color) => {
        const box = alertBox || preferenceAlertBox;
        if (!box) return;
        box.style.display = 'block';
        box.style.color = color;
        box.textContent = message;
    };

    const handleSavePreferences = async (alertBox) => {
        const subjectsRaw = subjectInput ? subjectInput.value.trim() : '';
        const aiToneRadio = document.querySelector('input[name="aiTone"]:checked');
        const schoolVal = schoolInput ? schoolInput.value.trim() : '';
        const notStudentVal = notStudentInput ? (notStudentInput.checked ? 1 : 0) : 0;

        // Enforce only one of school or not_student can be selected
        if (schoolVal && notStudentVal) {
            showPreferenceAlert(alertBox, "Select either School or Not a Student, not both.", 'red');
            return;
        }
        if (!schoolVal && !notStudentVal) {
            showPreferenceAlert(alertBox, "Select your School or check Not a Student.", 'red');
            return;
        }

        if (schoolVal) {
            const schoolSet = window.SCHOOL_SET;
            if (!schoolSet || schoolSet.size === 0) {
                showPreferenceAlert(alertBox, 'School list is loading. Please wait a moment.', 'red');
                return;
            }
            if (!schoolSet.has(schoolVal.trim().toLowerCase())) {
                showPreferenceAlert(alertBox, 'Select your school from the list.', 'red');
                return;
            }
        }

        if (!subjectsRaw) {
            showPreferenceAlert(alertBox, 'Enter at least one interested subject.', 'red');
            return;
        }

        if (!/^[\p{L}\s,]+$/u.test(subjectsRaw)) {
            showPreferenceAlert(alertBox, 'Only text, spaces, and commas are allowed.', 'red');
            return;
        }

        const subjects = subjectsRaw
            .split(',')
            .map(subject => subject.trim())
            .filter(subject => subject.length > 0);

        const uniqueSubjects = Array.from(new Set(subjects));

        if (uniqueSubjects.length === 0) {
            showPreferenceAlert(alertBox, 'Enter at least one interested subject.', 'red');
            return;
        }

        if (uniqueSubjects.length > 5) {
            showPreferenceAlert(alertBox, 'Maximum 5 values allowed.', 'red');
            return;
        }

        if (!aiToneRadio) {
            showPreferenceAlert(alertBox, 'Select an AI tone.', 'red');
            return;
        }

        const formData = new FormData();
        formData.append('action', 'preferences');
        formData.append('subjects', uniqueSubjects.join(', '));
        formData.append('aiTone', aiToneRadio.value);
        formData.append('school', schoolVal);
        formData.append('not_student', notStudentVal);

        try {
            const res = await fetch(API_URL, { method: 'POST', body: formData });
            const result = await res.json();
            if (result.success) {
                showPreferenceAlert(alertBox, 'Preferences saved successfully!', 'green');
                loadProfileData();
            } else {
                showPreferenceAlert(alertBox, 'Failed: ' + result.message, 'red');
            }
        } catch (err) {
            showPreferenceAlert(alertBox, 'Failed to save preferences.', 'red');
            console.error(err);
        }
    };

    if (savePreferenceBtn) {
        savePreferenceBtn.addEventListener('click', () => handleSavePreferences(preferenceAlertBox));
    }

    if (saveStudentVerificationBtn) {
        saveStudentVerificationBtn.addEventListener('click', () => handleSavePreferences(studentVerificationAlertBox));
    }

    // --- Enforce school / not_student exclusivity in UI ---
    if (schoolInput && notStudentInput) {
        // When typing in school, uncheck not_student if not empty
        schoolInput.addEventListener('input', () => {
            if (schoolInput.value.trim() !== '') {
                notStudentInput.checked = false;
            }
        });
        // When checking not_student, clear school input
        notStudentInput.addEventListener('change', () => {
            if (notStudentInput.checked) {
                schoolInput.value = '';
            }
        });
    }

    // --- Clear Memory ---
    if (clearMemoryBtn) {
        clearMemoryBtn.addEventListener('click', async () => {
            if (IS_GUEST) {
                notifyGuest('Log in to use memory.');
                return;
            }
            const formData = new FormData();
            formData.append('action', 'clearmemory');

            try {
                const res = await fetch(API_URL, { method: 'POST', body: formData });
                const result = await res.json();
                if (result.success) {
                    currentMemoryBox.textContent = 'No memory stored.';
                    alert('Memory cleared successfully!');
                } else {
                    alert('Failed to clear memory: ' + result.message);
                }
            } catch (err) {
                alert('Error clearing memory.');
                console.error(err);
            }
        });
    }

    // --- Billing Slider Logic ---
    const priceRange = document.getElementById('priceRange');
    const priceDisplay = document.getElementById('priceDisplay');
    const payButton = document.getElementById('payButton');

    if (priceRange && priceDisplay && payButton) {
        priceRange.addEventListener('input', () => {
            const amount = priceRange.value;
            priceDisplay.textContent = `Rs. ${amount}`;
            payButton.textContent = `Pay Rs. ${amount}`;
        });

        payButton.addEventListener('click', () => {
            const amount = priceRange.value;
            const baseUrl = (window.APP_BASE_URL||window.location.origin||"").replace(/\/$/,"");
            window.location.href = `${baseUrl}/pay/${amount}`;
        });
    }

    // --- Delete Account ---
    if (deleteAccountBtn && deleteAccountModal) {
        deleteAccountBtn.addEventListener('click', () => {
            deleteAccountModal.style.display = 'flex';
        });
    }
    if (cancelDeleteAccountBtn && deleteAccountModal) {
        cancelDeleteAccountBtn.addEventListener('click', () => {
            deleteAccountModal.style.display = 'none';
        });
    }
    if (deleteAccountModal) {
        deleteAccountModal.addEventListener('click', (event) => {
            if (event.target === deleteAccountModal) {
                deleteAccountModal.style.display = 'none';
            }
        });
    }
    if (confirmDeleteAccountBtn) {
        confirmDeleteAccountBtn.addEventListener('click', async () => {
            confirmDeleteAccountBtn.disabled = true;
            try {
                const formData = new FormData();
                formData.append('action', 'delete_account');
                const res = await fetch(API_URL, { method: 'POST', body: formData });
                const result = await res.json();
                if (result.success) {
                    const baseUrl = (window.APP_BASE_URL||window.location.origin||"").replace(/\/$/,"");
                    window.location.href = `${baseUrl}/auth/login`;
                } else {
                    alert(result.message || 'Failed to delete account.');
                    confirmDeleteAccountBtn.disabled = false;
                }
            } catch (err) {
                alert('Failed to delete account.');
                confirmDeleteAccountBtn.disabled = false;
            }
        });
    }

});


// Preference tab: Enforce either School or Not a student, not both
document.addEventListener('DOMContentLoaded', function() {
  const schoolInput = document.getElementById('schoolInput');
  const notStudentInput = document.getElementById('notStudentInput');
  if (schoolInput && notStudentInput) {
    // When user types in school, uncheck notStudent if not empty
    schoolInput.addEventListener('input', function() {
      if (schoolInput.value.trim() !== '') {
        notStudentInput.checked = false;
        notStudentInput.disabled = true;
      } else {
        notStudentInput.disabled = false;
      }
    });
    // When user checks notStudent, clear and disable school
    notStudentInput.addEventListener('change', function() {
      if (notStudentInput.checked) {
        schoolInput.value = '';
        schoolInput.disabled = true;
      } else {
        schoolInput.disabled = false;
      }
    });
    // On load, set correct state
    if (notStudentInput.checked) {
      schoolInput.value = '';
      schoolInput.disabled = true;
    }
    if (schoolInput.value.trim() !== '') {
      notStudentInput.checked = false;
      notStudentInput.disabled = true;
    }
  }
});
